-- path: schema/tables/dbo.Tuned.sql
CREATE TABLE [dbo].[Tuned] (
    [Id] int NOT NULL,
    [Code] varchar(10) NOT NULL
);
GO
CREATE NONCLUSTERED INDEX [IX_Tuned_Code] ON [dbo].[Tuned] ([Code])
    WITH (PAD_INDEX = ON, FILLFACTOR = 70, IGNORE_DUP_KEY = OFF, STATISTICS_NORECOMPUTE = ON,
          ALLOW_ROW_LOCKS = OFF, ALLOW_PAGE_LOCKS = OFF, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF, DATA_COMPRESSION = NONE);
GO
CREATE UNIQUE NONCLUSTERED INDEX [UX_Tuned_Id] ON [dbo].[Tuned] ([Id]) WITH (IGNORE_DUP_KEY = ON, DATA_COMPRESSION = ROW);
